// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmt, uint8 extraCalls) public {
        vm.assume(depositAmt >= 1);
        vm.assume(extraCalls <= 10);
        address actor = makeAddr("actor");
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();
        uint256 paid = 0;
        uint256 beforeBal = address(c).balance;
        for (uint256 i = 0; i < extraCalls + 1; i++) {
            uint256 preBalance = address(c).balance;
            vm.prank(actor);
            c.withdrawAll();
            uint256 postBalance = address(c).balance;
            paid += (preBalance - postBalance);
        }
        uint256 afterBal = address(c).balance;
        assertTrue(afterBal + paid == depositAmt);
    }
}
